"use client";

import * as React from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import styles from "../styles/badge.module.css";

export interface BadgeProps {
  /** Badge text (ignored when children are provided) */
  label?: string;
  /** Custom badge content */
  children?: React.ReactNode;
  /** Visual variant */
  variant?: "default" | "secondary" | "outline" | "success" | "warning" | "destructive";
  /** Size preset */
  size?: "sm" | "md" | "lg";
  /** Corner style */
  shape?: "pill" | "rounded";
  /** Show a leading status dot */
  dot?: boolean;
  /** Animate the dot with a soft radiating pulse */
  pulse?: boolean;
  /** Show a remove (x) button; the badge animates out when pressed */
  removable?: boolean;
  /** Called after the remove button is pressed */
  onRemove?: () => void;
  /** Fill color of the default variant */
  accentColor?: string;
  /** Pop in with a small spring on mount */
  animateIn?: boolean;
  /** Optional className merged onto the root */
  className?: string;
  /** Optional inline styles merged onto the root */
  style?: React.CSSProperties;
}

export function Badge({
  label = "In review",
  children,
  variant = "default",
  size = "md",
  shape = "pill",
  dot = true,
  pulse = true,
  removable = true,
  onRemove,
  accentColor = "#6366f1",
  animateIn = true,
  className = "",
  style,
}: BadgeProps) {
  const reduce = useReducedMotion();
  const [visible, setVisible] = React.useState(true);
  const text = typeof children === "string" ? children : label;

  const remove = () => {
    setVisible(false);
    onRemove?.();
  };

  return (
    <AnimatePresence initial={animateIn && !reduce}>
      {visible && (
        <motion.span
          key="badge"
          className={`${styles.root} ${className}`.trim()}
          data-variant={variant}
          data-size={size}
          data-shape={shape}
          style={{ "--mf-bd-accent": accentColor, ...style } as React.CSSProperties}
          initial={{ opacity: 0, scale: 0.8, y: 2 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: reduce ? 1 : 0.8 }}
          transition={reduce ? { duration: 0.1 } : { type: "spring", stiffness: 520, damping: 30 }}
        >
          {dot && (
            <span aria-hidden="true" className={styles.dot} data-pulse={pulse && !reduce ? "" : undefined} />
          )}
          <span className={styles.label}>{children ?? label}</span>
          {removable && (
            <button type="button" className={styles.remove} aria-label={`Remove ${text}`} onClick={remove}>
              <svg aria-hidden="true" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round">
                <path d="M18 6 6 18M6 6l12 12" />
              </svg>
            </button>
          )}
        </motion.span>
      )}
    </AnimatePresence>
  );
}

.root {
  --mf-bd-h: 1.5rem;
  --mf-bd-fs: 0.75rem;
  --mf-bd-px: 0.625rem;
  --mf-bd-bg: var(--mf-bd-accent, #6366f1);
  --mf-bd-fg: #ffffff;
  --mf-bd-border: transparent;
  --mf-bd-dot: currentColor;
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  height: var(--mf-bd-h);
  padding: 0 var(--mf-bd-px);
  border-radius: 999px;
  border: 1px solid var(--mf-bd-border);
  background-color: var(--mf-bd-bg);
  color: var(--mf-bd-fg);
  font-size: var(--mf-bd-fs);
  font-weight: 600;
  line-height: 1;
  letter-spacing: 0.01em;
  white-space: nowrap;
  vertical-align: middle;
  transition: background-color 160ms ease, color 160ms ease, border-color 160ms ease;
}

.root[data-size="sm"] {
  --mf-bd-h: 1.25rem;
  --mf-bd-fs: 0.6875rem;
  --mf-bd-px: 0.5rem;
}

.root[data-size="lg"] {
  --mf-bd-h: 1.875rem;
  --mf-bd-fs: 0.875rem;
  --mf-bd-px: 0.8125rem;
}

.root[data-shape="rounded"] {
  border-radius: 0.375rem;
}

.root[data-variant="secondary"] {
  --mf-bd-bg: var(--mf-surface-raised, #1b1b22);
  --mf-bd-fg: var(--mf-fg, #f4f4f6);
  --mf-bd-border: var(--mf-border, #2e2e38);
  --mf-bd-dot: var(--mf-bd-accent, #6366f1);
}

.root[data-variant="outline"] {
  --mf-bd-bg: transparent;
  --mf-bd-fg: var(--mf-fg, #f4f4f6);
  --mf-bd-border: var(--mf-border-strong, #52525b);
  --mf-bd-dot: var(--mf-bd-accent, #6366f1);
}

.root[data-variant="success"] {
  --mf-bd-bg: color-mix(in srgb, #22c55e 16%, transparent);
  --mf-bd-fg: #22c55e;
  --mf-bd-border: color-mix(in srgb, #22c55e 35%, transparent);
}

.root[data-variant="warning"] {
  --mf-bd-bg: color-mix(in srgb, #f59e0b 16%, transparent);
  --mf-bd-fg: #f59e0b;
  --mf-bd-border: color-mix(in srgb, #f59e0b 35%, transparent);
}

.root[data-variant="destructive"] {
  --mf-bd-bg: #ef4444;
  --mf-bd-fg: #ffffff;
}

.label {
  display: inline-flex;
  align-items: center;
}

.dot {
  position: relative;
  flex-shrink: 0;
  width: 0.4375rem;
  height: 0.4375rem;
  border-radius: 999px;
  background-color: var(--mf-bd-dot);
}

.dot[data-pulse]::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background-color: var(--mf-bd-dot);
  animation: mf-bd-pulse 1.8s cubic-bezier(0, 0, 0.2, 1) infinite;
}

.remove {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: calc(var(--mf-bd-h) - 0.5rem);
  height: calc(var(--mf-bd-h) - 0.5rem);
  margin-right: calc(var(--mf-bd-px) * -0.5);
  padding: 0;
  border: 0;
  border-radius: 999px;
  background-color: transparent;
  color: inherit;
  opacity: 0.7;
  cursor: pointer;
  transition: opacity 150ms ease, background-color 150ms ease, transform 150ms ease;
}

.remove:hover {
  opacity: 1;
  background-color: color-mix(in srgb, currentColor 18%, transparent);
}

.remove:active {
  transform: scale(0.88);
}

.remove:focus-visible {
  opacity: 1;
  outline: 2px solid var(--mf-fg, #e4e4e7);
  outline-offset: 1px;
}

@keyframes mf-bd-pulse {
  0% {
    opacity: 0.75;
    transform: scale(1);
  }
  75%,
  100% {
    opacity: 0;
    transform: scale(2.6);
  }
}

@media (prefers-reduced-motion: reduce) {
  .root,
  .remove {
    transition: none;
  }
  .dot::after {
    animation: none;
    display: none;
  }
}

