"use client";

import { useState } from "react";

const variants = {
  default: "bg-indigo-500 text-white border-transparent",
  secondary: "bg-zinc-800 text-zinc-100 border-zinc-700",
  outline: "bg-transparent text-zinc-100 border-zinc-600",
  success: "bg-emerald-500/15 text-emerald-500 border-emerald-500/35",
  warning: "bg-amber-500/15 text-amber-500 border-amber-500/35",
  destructive: "bg-red-500 text-white border-transparent",
};

export function BadgeTailwind({ label = "In review", variant = "default" as keyof typeof variants }) {
  const [shown, setShown] = useState(true);
  if (!shown) return null;
  return (
    <span className={`inline-flex h-6 items-center gap-1.5 rounded-full border px-2.5 text-xs font-semibold animate-in zoom-in-90 ${variants[variant]}`}>
      <span aria-hidden className="relative size-1.5 rounded-full bg-current"><span className="absolute inset-0 animate-ping rounded-full bg-current" /></span>
      {label}
      <button type="button" aria-label={`Remove ${label}`} onClick={() => setShown(false)} className="-mr-1 grid size-4 place-items-center rounded-full opacity-70 hover:bg-current/20 hover:opacity-100">×</button>
    </span>
  );
}
